static const std::shared_ptr<arrow::Schema> &CatalogInfoRecordSchema() {
	static const auto schema = arrow::schema({
	    arrow::field("name", arrow::utf8(), /*nullable=*/false),
	    arrow::field("implementation_version", arrow::utf8(), /*nullable=*/true),
	    arrow::field("data_version_spec", arrow::utf8(), /*nullable=*/true),
	    arrow::field("attach_option_specs", arrow::list(arrow::binary()), /*nullable=*/false),
	    arrow::field("releases", arrow::list(arrow::struct_({arrow::field("version", arrow::utf8(), /*nullable=*/false), arrow::field("released_at", arrow::timestamp(arrow::TimeUnit::MICRO, "UTC"), /*nullable=*/true), arrow::field("summary", arrow::utf8(), /*nullable=*/false), arrow::field("notes_url", arrow::utf8(), /*nullable=*/true)})), /*nullable=*/false),
	    arrow::field("source_url", arrow::utf8(), /*nullable=*/true),
	});
	return schema;
}

bool operator==(const CatalogInfo &a, const CatalogInfo &b) {
	return wire::Equal(a.name, b.name) &&
	       wire::Equal(a.implementation_version, b.implementation_version) &&
	       wire::Equal(a.data_version_spec, b.data_version_spec) &&
	       wire::Equal(a.attach_option_specs, b.attach_option_specs) &&
	       wire::Equal(a.releases, b.releases) &&
	       wire::Equal(a.source_url, b.source_url);
}

template <class Reader>
static void ReadCatalogInfo(Reader &r, CatalogInfo &out) {
	r.Required("name", out.name);
	r.Optional("implementation_version", out.implementation_version);
	r.Optional("data_version_spec", out.data_version_spec);
	r.Required("attach_option_specs", out.attach_option_specs);
	r.Required("releases", out.releases);
	r.Optional("source_url", out.source_url);
}

void ReadValue(const arrow::Array &array, int64_t i, CatalogInfo &out, const wire::Ctx &ctx) {
	wire::StructReader r(array, i, ctx, "CatalogInfo");
	ReadCatalogInfo(r, out);
}

std::shared_ptr<arrow::Array> BuildColumn(const std::shared_ptr<arrow::DataType> &type,
                                          const std::vector<const CatalogInfo *> &rows) {
	wire::StructColumn<CatalogInfo> c(type, rows);
	c.Put(0, &CatalogInfo::name);
	c.Put(1, &CatalogInfo::implementation_version);
	c.Put(2, &CatalogInfo::data_version_spec);
	c.Put(3, &CatalogInfo::attach_option_specs);
	c.Put(4, &CatalogInfo::releases);
	c.Put(5, &CatalogInfo::source_url);
	return c.Finish();
}

std::shared_ptr<arrow::RecordBatch> ToBatch(const CatalogInfo &value) {
	const auto &schema = CatalogInfoRecordSchema();
	return wire::BatchFromStruct(schema, BuildColumn(wire::StructTypeOf(schema), {&value}));
}

void FromBatch(const std::shared_ptr<arrow::RecordBatch> &batch, int64_t row, CatalogInfo &out,
               const std::string &worker_path) {
	wire::RowReader r(batch, row, "CatalogInfo", worker_path);
	ReadCatalogInfo(r, out);
}

